//! Voxel data of the chunks around the focus: generated by bounded jobs, dropped when the focus
//! moves away.

use std::collections::HashMap;
use std::sync::Arc;

use bevy::prelude::*;
use voxel_core::{Chunk, ChunkPos};
use voxel_gen::TerrainGenerator;

use super::jobs::{ChunkWorkers, Job};
use super::plan::ActivePlan;

/// The world's terrain generator, built from the world settings at startup.
#[derive(Debug, Clone, Resource)]
pub struct Terrain(pub TerrainGenerator);

/// Loaded voxel data. Bounded by the active plan: chunks outside it are dropped.
#[derive(Debug, Default, Resource)]
pub struct ChunkVoxels {
    chunks: HashMap<ChunkPos, Arc<Chunk>>,
}

impl ChunkVoxels {
    #[must_use]
    pub fn get(&self, pos: ChunkPos) -> Option<&Chunk> {
        self.chunks.get(&pos).map(Arc::as_ref)
    }

    /// A shared handle to the chunk, for jobs that read it off the main thread.
    #[must_use]
    pub fn shared(&self, pos: ChunkPos) -> Option<Arc<Chunk>> {
        self.chunks.get(&pos).cloned()
    }

    #[must_use]
    pub fn contains(&self, pos: ChunkPos) -> bool {
        self.chunks.contains_key(&pos)
    }

    #[must_use]
    pub fn len(&self) -> usize {
        self.chunks.len()
    }

    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.chunks.is_empty()
    }

    /// Heap memory held by voxel arrays; uniform chunks hold none (ADR 0012).
    #[must_use]
    pub fn heap_bytes(&self) -> usize {
        self.chunks.values().map(|chunk| chunk.heap_bytes()).sum()
    }
}

/// Generation jobs in flight, by chunk.
#[derive(Debug, Default, Resource)]
pub struct GenerationJobs {
    jobs: HashMap<ChunkPos, Job<Chunk>>,
}

impl GenerationJobs {
    #[must_use]
    pub fn len(&self) -> usize {
        self.jobs.len()
    }

    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.jobs.is_empty()
    }
}

pub(super) fn drop_far_voxels(
    plan: Res<ActivePlan>,
    mut voxels: ResMut<ChunkVoxels>,
    mut jobs: ResMut<GenerationJobs>,
) {
    if plan.is_changed() {
        voxels.chunks.retain(|&pos, _| plan.0.wants_voxels(pos));
        jobs.jobs.retain(|&pos, _| plan.0.wants_voxels(pos));
    }
}

pub(super) fn start_generation(
    plan: Res<ActivePlan>,
    terrain: Res<Terrain>,
    workers: Res<ChunkWorkers>,
    voxels: Res<ChunkVoxels>,
    mut jobs: ResMut<GenerationJobs>,
) {
    let budget = workers.budget();
    let room = budget.generation_in_flight.saturating_sub(jobs.jobs.len());
    let missing: Vec<ChunkPos> = plan
        .0
        .voxels()
        .iter()
        .copied()
        .filter(|&pos| !voxels.contains(pos) && !jobs.jobs.contains_key(&pos))
        .take(room.min(budget.generation_starts))
        .collect();
    for pos in missing {
        let terrain = terrain.0.clone();
        jobs.jobs.insert(
            pos,
            Job::start(*workers, move || terrain.generate_chunk(pos)),
        );
    }
}

pub(super) fn finish_generation(mut voxels: ResMut<ChunkVoxels>, mut jobs: ResMut<GenerationJobs>) {
    let mut done = Vec::new();
    for (&pos, job) in &mut jobs.jobs {
        if let Some(chunk) = job.poll() {
            done.push((pos, chunk));
        }
    }
    for (pos, chunk) in done {
        jobs.jobs.remove(&pos);
        voxels.chunks.insert(pos, Arc::new(chunk));
    }
}
